[package]
name = "mesh-talk-core"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
description = "Mesh-Talk core: a serverless, end-to-end-encrypted LAN messaging protocol — identity & device certificates, an encrypted event log with peer sync, Double Ratchet + sender-key forward secrecy, a Noise transport, LAN discovery, a store-and-forward post office, and the node runtime. UI-free; the basis for an SDK."

[features]
# TEST-ONLY: collapses the password KDFs (Argon2 + PBKDF2) to a trivial cost so downstream
# test suites (notably src-tauri, which links this crate normally and so doesn't see our own
# `cfg(test)`) don't pay ~12s per key derivation. Enable it ONLY from `[dev-dependencies]`
# (see src-tauri/Cargo.toml): Cargo does NOT activate a dev-dependency-only feature for normal
# `cargo build`/release builds, so production key strength is never affected. Never list this
# under `[dependencies]` or `default`.
fast-test-kdf = []

[lints]
workspace = true

[lib]
name = "mesh_talk_core"
path = "src/lib.rs"

# A headless node, usable on its own and as the reference SDK consumer.
[[bin]]
name = "mesh-talk-node"
path = "src/bin/mesh-talk-node.rs"

[dependencies]
rusqlite = { version = "0.41.0", default-features = false, features = ["bundled-sqlcipher-vendored-openssl", "cache", "blob"] }
serde_json = "1"
tokio = { workspace = true }
futures-util = "0.3"
serde = { workspace = true }
rand_core = { workspace = true }
base64 = { workspace = true }
hex = { workspace = true }
bincode = { workspace = true }
uuid = { workspace = true }
aes-gcm = { workspace = true }
pbkdf2 = { workspace = true }
sha2 = { workspace = true }
hkdf = { workspace = true }
ed25519-dalek = { workspace = true }
x25519-dalek = { workspace = true }
snow = { workspace = true }
zeroize = { workspace = true }
argon2 = { workspace = true }
socket2 = { workspace = true }
if-addrs = { workspace = true }
clap = { workspace = true }
# Logging facade only (no logger backend in the SDK); the host app's `log` logger captures
# these. Used for sync-cost telemetry so we can evaluate reconciliation scaling on real data.
log = { workspace = true }
tempfile = { workspace = true }
tar = "0.4.46"
image = { version = "0.25.10", default-features = false, features = ["png", "gif", "jpeg", "webp"] }

# Unix-only: safe lockfile open flags and a `kill(pid, 0)` probe for conservative
# legacy CLI lock detection. Already in the build graph via socket2/snow.
[target.'cfg(unix)'.dependencies]
libc = "0.2"

# Probe the PID recorded by the CLI data-dir lock after a Windows service restart.
[target.'cfg(windows)'.dependencies]
windows-sys = { version = "0.61.2", features = ["Win32_Foundation", "Win32_Networking_WinSock", "Win32_System_Threading", "Win32_Storage_FileSystem"] }

[dev-dependencies]
tokio = { workspace = true, features = ["test-util"] }
rand_chacha = "0.3" # seeded CSPRNG for deterministic property tests (rand_core 0.6 SeedableRng)
# Self-dev-dependency on our OWN crate, activating `fast-test-kdf`. This is the lever that
# makes the multi-process integration rigs fast: when Cargo builds the test targets it unifies
# features for `mesh-talk-core`, so the `mesh-talk-node` binary handed to the tests via
# `CARGO_BIN_EXE_mesh-talk-node` is ALSO compiled with `fast-test-kdf` — collapsing each node's
# cold start from ~60-70s (real Argon2/PBKDF2) to ~instant. Cargo does NOT activate a
# dev-dependency-only feature for `cargo build`/release, so production key strength is untouched.
mesh-talk-core = { path = ".", features = ["fast-test-kdf"] }
[package]
name = "mesh-talk-integrations"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
description = "Scoped local messaging capabilities for Mesh-Talk bots, scripts and agents."

[lints]
workspace = true

[dependencies]
hyper = { version = "1.7", default-features = false, features = ["http1", "server"] }
hyper-util = { version = "0.1", default-features = false, features = ["service", "tokio"] }
schemars = "1.0.4"
axum = { version = "0.8.9", default-features = false, features = ["http1", "json", "tokio"] }
mesh-talk-core = { path = "../mesh-talk-core" }
tokio = { workspace = true }
serde = { workspace = true }
serde_json = "1"
log = { workspace = true }
sha2 = { workspace = true }
hex = { workspace = true }
rand_core = { workspace = true }
uuid = { workspace = true }
clap = { workspace = true }
tempfile = { workspace = true }

[target.'cfg(unix)'.dependencies]
libc = "0.2"

[target.'cfg(windows)'.dependencies]
windows-sys = { version = "0.61.2", features = ["Win32_Foundation", "Win32_Security", "Win32_Security_Authorization", "REDACTED", "Win32_System_Memory", "Win32_System_Threading"] }

[dev-dependencies]
mesh-talk-core = { path = "../mesh-talk-core", features = ["fast-test-kdf"] }
tokio = { workspace = true, features = ["test-util"] }
[package]
name = "mesh-talk-mcp"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true

[lints]
workspace = true

[dependencies]
clap.workspace = true
mesh-talk-integrations = { path = "../mesh-talk-integrations" }
rmcp = { version = "3.5.1", default-features = false, features = ["server", "macros", "schemars", "transport-io"] }
serde.workspace = true
serde_json = "1"
tokio.workspace = true

[dev-dependencies]
rmcp = { version = "3.5.1", default-features = false, features = ["client"] }
mesh-talk-core = { path = "../mesh-talk-core", features = ["fast-test-kdf"] }
tempfile.workspace = true
"}
